import model.Admin;import model.Passenger;import model.AirlineStaff;import service.AuthenticationService;import service.UserService;// UC3 importsimport model.Seat;import model.SeatMap;import repo.SeatRepo;import service.SeatService;import service.SeatDisplayService;import controller.SeatController;import model.Booking;import model.Flight;import repo.BookingRepo;import service.BookingService;public class Main {    public static void main(String[] args) {        UserService service = new UserService();        // ---------------- USERS ----------------        Passenger passenger = new Passenger(                1,                "Bala",                "bala@gmail.com",                "9876543210",                "01-01-1999",                "P1001",                "bala",                "1234"        );        Admin admin = new Admin(                2,                "System Admin",                "admin@gmail.com",                "9999999999",                "10-02-1980",                "A1001",                "admin",                "admin123"        );        AirlineStaff staff = new AirlineStaff(                3,                "Staff User",                "staff@gmail.com",                "8888888888",                "20-05-1990",                "S1234",                "staff",                "staff123",                "Operations"        );        service.register(passenger);        service.register(admin);        service.register(staff);        service.displayAllUsers();        passenger.displayPermissions();        admin.displayPermissions();        staff.displayPermissions();        // ---------------- AUTH ----------------        AuthenticationService auth = new AuthenticationService();        boolean login = auth.login(passenger, "john", "1234");        System.out.println("Login Success: " + login);        // ---------------- UC3 SEAT MODULE ----------------        SeatMap seatMap = new SeatMap();        // Creating sample seats        seatMap.addSeat(new Seat("1A", "WINDOW", true, 500, true, true));        seatMap.addSeat(new Seat("1B", "MIDDLE", false, 0, false, false));        seatMap.addSeat(new Seat("1C", "AISLE", true, 300, false, true));        seatMap.addSeat(new Seat("2A", "WINDOW", false, 0, false, false));        seatMap.addSeat(new Seat("2B", "MIDDLE", false, 0, false, false));        // Repo + Service setup        SeatRepo repo = new SeatRepo(seatMap);        SeatService seatService = new SeatService(repo, seatMap);        SeatDisplayService display = new SeatDisplayService(seatMap);        SeatController controller = new SeatController(seatService);        // Display seat map        display.displaySeatMap();        // Seat selection test        System.out.println("\n--- Seat Booking ---");        System.out.println(controller.selectSeat("1A", true));        // Display after booking        display.displaySeatMap();        // ======================// UC4 BOOKING MANAGEMENT// ======================        System.out.println("\n========== UC4 BOOKING ==========");// Create a sample Flight        Flight flight = new Flight(                "AI101",                "Chennai",                "Delhi",                6500        );// Booking Service        BookingService bookingService = new BookingService();// Create Booking        Booking booking = bookingService.createBooking(flight);// Add Passenger        bookingService.addPassenger(booking, passenger);// Select Seat        Seat selectedSeat = repo.findSeatById("1A");        bookingService.selectSeat(booking, selectedSeat);// Calculate Fare        bookingService.calculateFare(booking);// Confirm Booking        bookingService.confirmBooking(booking);// Display Booking        bookingService.displayBooking(booking);// Retrieve Booking using PNR        System.out.println("\nSearching by PNR...");        Booking foundBooking =                bookingService.searchByPNR(booking.getPnr());        bookingService.displayBooking(foundBooking);// Display Booking History        System.out.println("\nBooking History");        bookingService.displayBookingHistory();    }}